scripts.modular_exp:
def solve(inputs: dict) -> float:
    base = inputs['BASE']
    exp = inputs['EXP']
    mod = inputs['MOD']

    result = pow(base, exp, mod)
    return float(result)

scripts.iterated_quadratic:
def solve(inputs: dict) -> float:
    x = inputs['X']
    c = inputs['C']
    mod = inputs['MOD']
    k = inputs['K']

    for _ in range(k):
        x = (x * x + c) % mod

    return float(x)

